 import React, { useState, useEffect } from 'react';
 import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
 import Draft from './components/Draft';
 import NotesList from './components/NotesList';

 const App = () => {
   // ---- State -------------------------------------------------
   const [notes, setNotes] = useState([]);
   const [draft, setDraft] = useState('');

   // ---- Load from storage on mount ---------------------------
   useEffect(() => {
     const savedNotes = localStorage.getItem('pocketNotes_notes');
     if (savedNotes) setNotes(JSON.parse(savedNotes));

     const savedDraft = localStorage.getItem('pocketNotes_draft');
     if (savedDraft) setDraft(savedDraft);
   }, []);

   // ---- Persist notes -----------------------------------------
   useEffect(() => {
     localStorage.setItem('pocketNotes_notes', JSON.stringify(notes));
   }, [notes]);

   // ---- Persist draft (clear after save) ----------------------
   useEffect(() => {
     if (draft === '') {
       localStorage.removeItem('pocketNotes_draft');
     } else {
       localStorage.setItem('pocketNotes_draft', draft);
     }
   }, [draft]);

   // ---- Save – one note, clear draft --------------------------
   const saveNote = () => {
     if (!draft.trim()) return; // ignore empty saves

     const newNote = {
       id: Date.now().toString(),
       content: draft,
       createdAt: new Date().toISOString(),
     };

     setNotes(prev => [...prev, newNote]); // append exactly one
     setDraft(''); // clear UI & storage
   };

   // ---- Render ------------------------------------------------
   return (
     <Router>
       <nav>
         <Link to="/draft">Draft</Link> <span> </span>
         <Link to="/my-notes">My notes</Link>
       </nav>

       <Routes>
         <Route
           path="/draft"
           element={
             <Draft
               draft={draft}
               setDraft={setDraft}
               onSave={saveNote}
             />
           }
         />
         <Route
           path="/my-notes"
           element={<NotesList notes={notes} />}
         />
       </Routes>
     </Router>
   );
 };

 export default App;
